var i={en:`Editors can stay offline for 20 minutes and return with conflicting operations. Changes must be reconciled without silently erasing work.`,ua:`Редактори можуть бути офлайн 20 хвилин і повернутися з конфліктними операціями. Зміни треба узгодити без непомітного стирання роботи.`};var a={en:[`Add pending local operations and server reconciliation.`,`Choose CRDT, OT or server ordering with rationale.`,`Model duplicate replay, snapshots and conflict notifications.`],ua:[`Додай локальну чергу змін і серверне узгодження.`,`Обери CRDT, OT або серверний порядок з аргументами.`,`Змоделюй повтори, знімки та повідомлення конфліктів.`]};var o=[{en:`Operations have stable IDs and deduplication.`,ua:`Операції мають сталі ID й дедуплікацію.`},{en:`No offline overwrite is silently treated as success.`,ua:`Жоден офлайн-перезапис не вважається тихо успішним.`}];var s={scenario:i,tasks:a,checks:o};export{o as checks,s as default,i as scenario,a as tasks};